import React from "react";
import styled from "styled-components";

const StyledPageContainer = styled.div`
  display: flex;
  flex-direction: column;
  min-height: 100%;
  text-align: left;
  padding: 16px;
  background-color: #FFFFFF;
  position: relative;
`;

export const PageContainer: React.FC<{ children: React.ReactNode; className?: string }> = ({ children, className }) => (
  <StyledPageContainer className={className}>
    <Watermark>Preview</Watermark>
    {children}
  </StyledPageContainer>
);

const StyledPageContainerDialog = styled(StyledPageContainer)`
  padding: 8px;
`;

export const PageContainerDialog: React.FC<{ children: React.ReactNode; className?: string }> = ({ children, className }) => (
  <StyledPageContainerDialog className={className}>
    <Watermark>Preview</Watermark>
    {children}
  </StyledPageContainerDialog>
);

export const PageContent = styled.div`
  width: round(calc(100% - 1px), 2px);
  display: flex;
  flex-direction: row;
  min-height: 100%;
  gap: 24px;
`;

export const ContentColumn = styled.div`
  flex: 1;
  min-width: 360px;
  max-width: 720px;
  display: flex;
  flex-direction: column;
  gap: 8px;
`;

export const ContentColumnSmall = styled(ContentColumn)`
  max-width: 600px;
`;

export const Watermark = styled.div`
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-45deg);
  font-size: 72px;
  font-weight: bold;
  color: rgba(0, 0, 0, 0.05);
  pointer-events: none;
  user-select: none;
  z-index: 1000;
  text-transform: uppercase;
  letter-spacing: 8px;
`;