import styled from "styled-components";


const DividerCaption = styled.label`
    position: absolute;
    top: -8px;
    left: 4px;
    padding: 0px 4px;
    background-color: #FFFFFF;`

const Divider = styled.div`
    position: relative;    
    display: flex;
    flex-direction: column;
    width: 100%;
    justify-content: flex-start;
    padding: 15px 7px 7px 7px;
    gap: 8px;
    margin-top: 8px;
    border: 1px solid rgb(217, 219, 221);`

interface FormDividerInput {
    label: string;
    children?: React.ReactNode;
}

const FormDivider: React.FC<FormDividerInput> = ({ label, children }) => {
    return (
        <Divider>
            <DividerCaption>{label}</DividerCaption>
            {children}
        </Divider>
    )
}

export default FormDivider;